import co.sena.agendamiento.service.Validacion;import java.time.*;public class PruebaValidacion{public static void main(String[] args){var n=LocalDateTime.of(2026,1,1,10,0);Validacion.cita(1,1,n.plusHours(1),n);System.out.println("OK fecha futura");rechazo(()->Validacion.cita(1,1,n.minusHours(1),n));rechazo(()->Validacion.cita(0,1,n.plusHours(1),n));Validacion.estado("ATENDIDA");Validacion.estado("CANCELADA");System.out.println("OK estados permitidos");rechazo(()->Validacion.estado("OTRO"));}static void rechazo(Runnable r){try{r.run();throw new AssertionError("Debía rechazar");}catch(IllegalArgumentException e){System.out.println("OK rechazo de dato inválido");}}}